      [("S Urgences vitales Triage 144 REGA","On appelle le 144 devant une baisse de vigilance, une convulsion ou un déficit après un choc à la tête."),("Q Radioprotection Smarter Medicine","On applique une règle de décision validée pour éviter les scanners inutiles, surtout chez l'enfant."),("F Droit médical suisse","On peut aviser l'autorité de protection de l'enfant malgré le secret professionnel.")],
      (["On évalue le GCS, les pupilles et les signes de gravité.","On applique une règle de décision pour le scanner."],[("d'abord","médecin des urgences","Il mesure le GCS et les pupilles et cherche signes de base, embarrure, déficit et anticoagulant."),("en même temps","radiologue","Il fait le scanner sans injection et rend un compte rendu provisoire dans l'heure."),("ensuite","neurochirurgien","Il évalue toute anomalie à portée chirurgicale, une fuite de LCS ou une lésion pénétrante.")]),
      (["On décide la sortie ou l'observation.","On remet des consignes écrites."],[("d'abord","médecin des urgences","Il décide avec le patient la sortie ou l'observation selon l'anticoagulant, l'entourage et la protection de l'enfant."),("ensuite","infirmière","Elle surveille GCS, pupilles et constantes selon le rythme de NICE si le patient reste."),("puis","médecin de famille","Il revoit le patient entre 2 et 14 jours et reçoit une lettre dans les 48 heures.")]),
